        function App() {
          const headerRef = React.useRef(null)
          const expandedRef = React.useRef(null)

          return (
            <Space gap={24} align="start">
              <div
                ref={headerRef}
                className={dropdownMenuPreviewClassName}
                style={{ position: 'relative', minWidth: 280 }}
              >
                <Dropdown
                  visible
                  trigger={[]}
                  placement="bottomLeft"
                  getPopupContainer={() => headerRef.current}
                  overlay={[
                    {
                      type: 'submenu',
                      title: 'Submenu',
                      description: 'Some description',
                      children: [{ children: 'Nested item' }],
                    },
                    {
                      type: 'submenu',
                      title: 'Submenu with after',
                      componentsAfter: [<Badge mode="neutral" text="25" />],
                      children: [{ children: 'Item 1' }, { children: 'Item 2' }],
                    },
                    {
                      type: 'submenu',
                      title: 'Disabled submenu',
                      disabled: true,
                      description: 'With tooltip',
                      tooltip:
                        'Lorem ipsum dolor sit amet, consectetur adipiscing elit',
                      children: [{ children: 'Hidden' }],
                    },
                  ]}
                >
                  <span style={{ display: 'block', width: 1, height: 1 }} />
                </Dropdown>
              </div>

              <div
                ref={expandedRef}
                className={dropdownMenuPreviewClassName}
                style={{ position: 'relative', minWidth: 280, minHeight: 320 }}
              >
                <Dropdown.Menu
                  getPopupContainer={() => expandedRef.current}
                  triggerSubMenuAction="click"
                  defaultOpenKeys={['submenu', 'sub-submenu']}
                >
                  <Dropdown.GroupTitle>Раскрытый список</Dropdown.GroupTitle>
                  <Dropdown.MenuDivider />
                  <Dropdown.SubMenu
                    key="submenu"
                    eventKey="submenu"
                    title="SubMenuItem 1.1"
                  >
                    <Dropdown.MenuItem>MenuItem 2.1</Dropdown.MenuItem>
                    <Dropdown.SubMenu
                      key="sub-submenu"
                      eventKey="sub-submenu"
                      title="SubMenuItem 2.2"
                    >
                      <Dropdown.MenuItem>MenuItem 3.1</Dropdown.MenuItem>
                      <Dropdown.MenuItem>MenuItem 3.2</Dropdown.MenuItem>
                    </Dropdown.SubMenu>
                    <Dropdown.MenuItem>MenuItem 2.3</Dropdown.MenuItem>
                  </Dropdown.SubMenu>
                  <Dropdown.MenuItem>MenuItem 1.2</Dropdown.MenuItem>
                </Dropdown.Menu>
              </div>
            </Space>
          )
        }
